if (-not (Test-Path $BannerlordRoot)) {
    throw "Bannerlord root does not exist: $BannerlordRoot"
}

$ilspycmd = Get-IlspyCmdCommand
$assemblyMap = Get-AssemblyMap
$gameVersion = Get-GameVersion -BannerlordRoot $BannerlordRoot
$normalizedGameVersion = Get-NormalizedVersion -GameVersion $gameVersion
$Assemblies = if ($Assemblies -and $Assemblies.Count -gt 0) { $Assemblies } else { @($assemblyMap.Keys) }

if ($normalizedGameVersion -lt [version]'1.3') {
    $navalDlcAssemblies = @($Assemblies | Where-Object { $_ -like 'NavalDLC*' })
    if ($navalDlcAssemblies.Count -gt 0) {
        Write-Warning "Skipping NavalDLC assemblies for $gameVersion because NavalDLC is only available in v1.3 and later."
        $Assemblies = @($Assemblies | Where-Object { $_ -notlike 'NavalDLC*' })
    }
}

$decompilerOutput = Join-Path $DecompilerOutputRoot $gameVersion

New-Item -ItemType Directory -Force -Path $decompilerOutput | Out-Null

foreach ($assemblyName in $Assemblies) {
    if (-not $assemblyMap.Contains($assemblyName)) {
        throw "Unknown assembly key: $assemblyName"
    }

    $dllPath = Join-Path $BannerlordRoot $assemblyMap[$assemblyName]
    if (-not (Test-Path $dllPath)) {
        Write-Warning "Skipping missing assembly: $dllPath"
        continue
    }

    $outputPath = Join-Path $decompilerOutput $assemblyName
    New-Item -ItemType Directory -Force -Path $outputPath | Out-Null

    Write-Host "Decompiling $assemblyName..."
    & $ilspycmd -p -o $outputPath $dllPath
}

Write-Host "Detected game version: $gameVersion"
Write-Host "Done. Decompiled output: $decompilerOutput"
